  temp += 14.5; // Thermal heat surge under cyberattack
}
const loadPct = Number((45.0 + Math.random() * 30.0).toFixed(1));

// 6. Select Exact 39-Feature Dataset Vector
let baseVector;
let attackLabel;
if (attackMode === 1) {
  attackLabel = 'DDoS / Flood Attack';
  const idx = Math.floor(Math.random() * DDOS_POOLS.length);
  baseVector = DDOS_POOLS[idx];
