  attackLabel = 'Benign Traffic (Normal)';
  const idx = Math.floor(Math.random() * BENIGN_POOLS.length);
  baseVector = BENIGN_POOLS[idx];
}

// Clone vector and apply realistic jitter on continuous telemetry metrics
const flow_stats = baseVector.map((val, i) => {
  if ([3, 30, 35, 36].includes(i) && val > 0) {
    const jitter = 1.0 + (Math.random() * 0.04 - 0.02);
    return Number((val * jitter).toFixed(4));
  }
  return val;
});

